function validate([edges1, edges2]) {
  const check = (edges, name) => {
    if (!Array.isArray(edges) || edges.length > 99999) return `${name} has at most 99999 edges.`;
    const n = edges.length + 1;
    const parent = Array.from({ length: n }, (_, i) => i);
    const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
    for (const e of edges) {
      if (!Array.isArray(e) || e.length !== 2 || !e.every(v => Number.isInteger(v) && v >= 0 && v < n)) return `Each edge of ${name} joins two nodes from 0 to ${n - 1}.`;
      const a = find(e[0]), b = find(e[1]);
      if (a === b) return `${name} must form a tree (no cycles or repeated edges).`;
      parent[a] = b;
    }
    return null;
  };
  return check(edges1, 'edges1') ?? check(edges2, 'edges2');
}

