function minimumDiameterAfterMerge(edges1, edges2) {
  const farthest = (graph, start) => {
    const dist = new Array(graph.length).fill(-1);
    dist[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      for (const next of graph[node]) {
        if (dist[next] === -1) {
          dist[next] = dist[node] + 1;
          queue.push(next);
        }
      }
    }
    const last = queue[queue.length - 1];
    return [last, dist[last]];
  };

  const diameter = (edges) => {
    const graph = Array.from({ length: edges.length + 1 }, () => []);
    for (const [a, b] of edges) {
      graph[a].push(b);
      graph[b].push(a);
    }
    const [end] = farthest(graph, 0);
    return farthest(graph, end)[1];
  };

  const d1 = diameter(edges1);
  const d2 = diameter(edges2);
  const joined = Math.ceil(d1 / 2) + Math.ceil(d2 / 2) + 1;
  return Math.max(d1, d2, joined);
}

