function minimumDiameterAfterMerge(edges1, edges2) {
  const n = edges1.length + 1, m = edges2.length + 1, total = n + m;
  let best = Infinity;
  for (let a = 0; a < n; a++)
    for (let b = 0; b < m; b++) {
      const dist = Array.from({ length: total }, (_, i) => Array.from({ length: total }, (_, j) => (i === j ? 0 : Infinity)));
      const link = (u, v) => { dist[u][v] = 1; dist[v][u] = 1; };
      for (const [u, v] of edges1) link(u, v);
      for (const [u, v] of edges2) link(n + u, n + v);
      link(a, n + b);
      for (let k = 0; k < total; k++)
        for (let i = 0; i < total; i++)
          for (let j = 0; j < total; j++)
            if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
      let widest = 0;
      for (let i = 0; i < total; i++) for (let j = 0; j < total; j++) widest = Math.max(widest, dist[i][j]);
      best = Math.min(best, widest);
    }
  return best;
}

