function generate(rand, size) {
  const tree = (n, shape) => {
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
    const edges = [];
    for (let i = 1; i < n; i++) {
      let parent;
      if (shape === 'path') parent = i - 1;
      else if (shape === 'star') parent = 0;
      else if (shape === 'deep') parent = Math.max(0, i - 1 - Math.floor(rand() * 3));
      else parent = Math.floor(rand() * i);
      edges.push(rand() < 0.5 ? [order[parent], order[i]] : [order[i], order[parent]]);
    }
    for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
    return edges;
  };
  const shapes = ['random', 'random', 'path', 'star', 'deep'];
  const shape = () => shapes[Math.floor(rand() * shapes.length)];
  if (size === 'large') return [tree(1500 + Math.floor(rand() * 502), shape()), tree(1500 + Math.floor(rand() * 502), shape())];
  return [tree(1 + Math.floor(rand() * 7), shape()), tree(1 + Math.floor(rand() * 7), shape())];
}
